"""Diverse, strictly contamination-free bilingual (FR/EN) short coding prompts for CODELALA v3.

Every prompt is 1-3 natural sentences (matching real user queries) and is checked against
STRICT_HELD_OUT so NONE of the 12 held-out eval concepts (flappy, snake, pong, breakout,
memory, tictactoe, todo, calculator, pomodoro, 2048, minesweeper, paint) ever appear.
"""
import re

STRICT_HELD_OUT = re.compile(
    r"flap|bird|helicopt|copter|snake|serpent|pong|breakout|brick|arkanoid|"
    r"\bmemory\b|matching.?pair|card.?match|tic.?tac|morpion|noughts|"
    r"\bto[- ]?do\b|\btodo\b|task.?list|liste de t[aâ]ches|calculat|pomodoro|"
    r"\b2048\b|minesweeper|d[eé]mineur|\bpaint\b|drawing.?app|draw on|whiteboard|sketch",
    re.I,
)

