# Verify ZERO overlap with STRICT_HELD_OUT!
for pid, kind, prompt in WEBAPP_PROMPTS:
    if STRICT_HELD_OUT.search(pid) or STRICT_HELD_OUT.search(prompt):
        raise ValueError(f"CONTAMINATION DETECTED in {pid}: {prompt}")

if __name__ == "__main__":
    print(f"Verified {len(WEBAPP_PROMPTS)} strictly clean web-app/game/sim prompts.")
    by_kind = {}
    for _, k, _ in WEBAPP_PROMPTS:
        by_kind[k] = by_kind.get(k, 0) + 1
    print("Breakdown:", by_kind)
